:var(--cyan);margin-right:7px;font-style:normal}.battlefield{min-width:0;border:1px solid var(--line);display:flex;flex-direction:column}.map-head{height:54px;background:#1a2324;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid var(--line)}.map-head small{display:block;font:8px 'JetBrains Mono';color:var(--muted);margin-bottom:3px}.map-head b{font-size:13px;letter-spacing:.1em}.map-head button{background:transparent;border:1px solid var(--line);color:#9eaaa6;font:9px 'JetBrains Mono';height:28px}.map{position:relative;flex:1;overflow:hidden;background:#242e2b}.grid{position:absolute;inset:0;background-image:linear-gradient(rgba(128,150,143,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(128,150,143,.09) 1px,transparent 1px);background-size:54px 54px}.grid:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 45% 45%,transparent 0,rgba(13,18,18,.42) 100%),repeating-linear-gradient(163deg,transparent 0 5px,rgba(255,255,255,.012) 6px 7px)}.terrain.ridge{position:absolute;width:38%;height:18%;border:1px solid rgba(136,153,145,.18);border-left:0;border-right:0;transform:rotate(-18deg);border-radius:50%;box-shadow:0 -7px rgba(140,155,147,.06),0 -14px rgba(140,155,147,.04)}.r1{left:-8%;top:26%}.r2{right:-9%;top:12%}.river{position:absolute;width:80px;height:120%;left:57%;top:-10%;transform:rotate(20deg);background:rgba(67,108,105,.24);border-left:2px solid rgba(132,164,156,.12);border-right:2px solid rgba(132,164,156,.12)}.road{position:absolute;height:15px;width:90%;background:rgba(150,145,118,.08);border-top:1px dashed rgba(150,145,118,.13);border-bottom:1px dashed rgba(150,145,118,.13)}.road1{left:-5%;top:64%;transform:rotate(-8deg)}.road2{left:38%;top:45%;transform:rotate(38deg);width:70%}.contour{position:absolute;color:rgba(180,193,186,.18);font:700 46px 'JetBrains Mono';border:1px solid rgba(180,193,186,.06);width:90px;height:90px;border-radius:50%;display:flex;align-items:center;padding-left:12px}.c1{left:7%;top:12%}.c2{left:65%;top:59%}.c3{left:77%;top:12%}.node{position:absolute;z-index:3;transform:translate(-50%,-50%);text-align:center}.node span{display:flex;width:34px;height:34px;margin:auto;align-items:center;justify-content:center;border:1px solid #71817d;background:#273330;font-size:16px}.node b{display:block;white-space:nowrap;margin-top:5px;font:700 8px 'JetBrains Mono';text-shadow:0 1px 3px #000}.node.own span{border-color:var(--cyan);color:var(--cyan)}.node.enemy span{border-color:var(--red);color:var(--red)}.node.neutral span{border-color:#b2aa79;color:#d0ca9c}.unit{position:absolute;z-index:5;width:32px;height:32px;transform:translate(-50%,-50%);display:flex;align-items:center;justify-content:center;cursor:pointer}.unit span{width:25px;height:25px;background:#273f3c;border:1px solid var(--cyan);color:var(--cyan);display:flex;align-items:center;justify-content:center;font-size:11px;clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%)}.unit i{position:absolute;bottom:-7px;width:6px;height:3px;border-left:1px solid var(--cyan);border-right:1px solid var(--cyan)}.enemy-unit span{background:#4a302c;border-color:var(--red);color:var(--red)}.enemy-unit i{border-color:var(--red)}.selected:before{content:"";position:absolute;width:38px;height:38px;border:1px solid var(--cyan);transform:rotate(45deg);animation:spin 8s linear infinite}@keyframes spin{to{transform:rotate(405deg)}}.pulse{animation:pulse .6s}@keyframes pulse{50%{filter:brightness(2);transform:translate(-50%,-50%) scale(1.35)}}.scan{position:absolute;width:200px;height:200px;border:1px solid rgba(117,210,195,.07);border-radius:50%;left:10%;top:38%;animation:scan 7s ease-in-out infinite}@keyframes scan{50%{left:60%;top:20%}}.map-foot{height:34px;background:#1a2324;border-top:1px solid var(--line);display:flex;align-items:center;padding:0 14px;gap:22px}.map-foot span{font:8px 'JetBrains Mono';color:#95a29e}.dot{display:inline-block;width:5px;height:5px;margin-right:5px}.cyan{background:var(--cyan)}.red{background:var(--red)}.gray{background:#aaa57d}.map-foot b{margin-left:auto;font:8px 'JetBrains Mono';color:#758580}.orders{padding:16px}.selection{height:66px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:8px;display:grid;grid-template-columns:1fr auto;align-content:center}.selection small{grid-column:1/-1;font:8px 'JetBrains Mono';color:var(--muted)}.selection b{font-size:16px}.selection span{font:8px 'JetBrains Mono';color:var(--cyan);align-self:center}.order{width:100%;height:48px;margin-top:6px;background:#20292a;border:1px solid #344143;color:var(--text);display:grid;grid-template-columns:1fr 48px 20px;align-items:center;text-align:left;padding:0 10px;font-family:'Barlow Condensed';cursor:pointer}.order:hover{border-color:var(--cyan);background:#263335}.order b{text-transform:uppercase;font-size:14px}.order small{font:8px 'JetBrains Mono';color:var(--muted)}.order kbd{font:9px 'JetBrains Mono';color:#71807c}.end{margin-top:auto;height:54px;background:var(--cyan);border:0;color:#10201e;font-weight:700;letter-spacing:.1em;cursor:pointer}.end span{float:right;margin-right:14px;font-size:18px}#toast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,20px);background:#d8e3de;color:#17201f;padding:9px 16px;font:700 9px 'JetBrains Mono';opacity:0;transition:.25s;z-index:20}#toast.show{opacity:1;transform:translate(-50%,0)}
